// /how-it-works — Meeticulous "How It Works" page.
//
// Ported from the standalone "howItWorks" design (React/Vite). All visual code
// lives under howitworks-v2/. The design's 3 CSS files (variables/global/
// how-it-works, ~3.7k lines) are scoped under `.hiw-lp` in howitworks.scoped.css
// (auto-generated by scratchpad/scope-css-hiw.cjs) so its resets + generic
// classes (.container, .section, .btn, ...) never touch the rest of the app.
//
// The global Navbar + Footer wrap this route (this file drops the design's own
// Navbar/Footer and stays out of App.jsx's hideNavbar list). This is the
// route-level page — distinct from the homepage section at
// components/home/HowItWorks.jsx.
import Seo from '../components/common/Seo';
import { ogCard } from '../config/ogImages';
import { SITE_URL, faqJsonLd } from '../utils/seo';
import { faqs } from './howitworks-v2/data/howItWorksData';
import './howitworks-v2/howitworks.scoped.css';

import ProcessOverview from './howitworks-v2/components/howItWorks/ProcessOverview';
import MainDemoVideo from './howitworks-v2/components/howItWorks/MainDemoVideo';
import CustomerJourney from './howitworks-v2/components/howItWorks/CustomerJourney';
import TutorialLibrary from './howitworks-v2/components/howItWorks/TutorialLibrary';
import AutomationFlow from './howitworks-v2/components/howItWorks/AutomationFlow';
import BenefitsComparison from './howitworks-v2/components/howItWorks/BenefitsComparison';
import FAQSection from './howitworks-v2/components/howItWorks/FAQSection';
import FinalCTA from './howitworks-v2/components/howItWorks/FinalCTA';
import StickyDemoButton from './howitworks-v2/components/howItWorks/StickyDemoButton';
import DemoModal from './howitworks-v2/components/howItWorks/DemoModal';
import VideoModal from './howitworks-v2/components/common/VideoModal';

const HOW_IT_WORKS_JSONLD = faqJsonLd({
  // data faqs use {question, answer}; faqJsonLd wants {q, a}.
  faqs: faqs.map((f) => ({ q: f.question, a: f.answer })),
});

export default function HowItWorks() {
  return (
    <div className="hiw-lp">
      <Seo
        title="How Meeticulous works — get booked and paid with one link"
        description="See how Meeticulous gets India's creators and professionals booked and paid: share one link, clients book and pay over UPI, with reminders and calendar sync handled."
        canonical={`${SITE_URL}/how-it-works`}
        image={ogCard('how-it-works', 'png')}
        jsonLd={HOW_IT_WORKS_JSONLD}
      />

      <main className="how-it-works-page">
        <ProcessOverview />
        {/* Hidden until real videos ready — placeholder/dummy YouTube content. Do not delete. */}
        {/* <MainDemoVideo /> */}
        <CustomerJourney />
        {/* Hidden until real videos ready — placeholder/dummy YouTube content. Do not delete. */}
        {/* <TutorialLibrary /> */}
        <AutomationFlow />
        <BenefitsComparison />
        <FAQSection />
        <FinalCTA />
        <StickyDemoButton />
        <DemoModal />
        <VideoModal />
      </main>
    </div>
  );
}
